def get_zone_for_location(location_name: str) -> str:
    """Auto-detect zone from a location name."""
    if not location_name:
        return "Central"
    loc = location_name.lower().strip()
    for key, zone in LOCATION_TO_ZONE.items():
        if key in loc:
            return zone
    return "Central"  # default fallback


def get_station_for_location(location_name: str) -> str:
    """Auto-assign the nearest police station code from a location name."""
    if not location_name:
        return "BLR_CYB_PS"
    loc = location_name.lower().strip()
    for key, code in LOCATION_TO_STATION.items():
        if key in loc:
            return code
    return "BLR_CYB_PS"  # default: cyber crime cell
